@verbatim
<template id="finance-transactions-template">
<template v-if="['month','transactions'].includes(view.name)"><nav v-if="view.name==='month'" class="period-navigation" aria-label="Рік та місяць"><label class="year-picker"><span class="visually-hidden">Оберіть рік</span><custom-select :model-value="currentYear?.id" :options="state.years.map(year=>({label:String(year.name),value:year.id}))" :disabled="loading||saving" aria-label="Оберіть рік" variant="pill" @change="switchYear"></custom-select></label><div class="chips"><a v-for="month in months" :key="month.id" :href="url('/month/'+month.id)" :class="['chip',{selected:month.id===currentMonth?.id}]" :aria-current="month.id===currentMonth?.id?'page':null" @click.prevent="navigate('/month/'+month.id)">{{month.name}}</a></div></nav><div :class="['transactions-columns',{'full-width':view.name==='transactions'}]"><section class="panel transaction-panel"><div class="section-heading"><div><h2>Історія витрат</h2><p>{{state.transactions.total}} транзакцій · {{money(state.transactions.spent)}} грн за фільтром</p></div><div class="transaction-heading-actions"><button v-if="view.name==='month'" class="button primary" :disabled="loading||!state.budgets.length" @click="openDialog('transaction')"><icon name="plus"></icon>Додати транзакцію</button><span class="surface-icon"><icon name="wallet"></icon></span></div></div><form class="filters" @submit.prevent="applyFilters"><label class="search-field filter-search"><icon name="search"></icon><input v-model="filters.title" @input="scheduleSearch" type="search" placeholder="Пошук за описом" aria-label="Опис транзакції"></label><label><span class="visually-hidden">Категорія</span><custom-select v-model="filters.category_id" :options="[{label:'Усі категорії',value:''},...state.categories.map(category=>({label:category.name,value:category.id}))]" aria-label="Категорія" @change="applyFilters"></custom-select></label><label><span class="visually-hidden">Автор</span><custom-select v-model="filters.user_id" :options="[{label:'Усі автори',value:''},...state.users.map(author=>({label:author.name,value:author.id}))]" aria-label="Автор" @change="applyFilters"></custom-select></label><label><span class="visually-hidden">Спосіб оплати</span><custom-select v-model="filters.type" :options="[{label:'Усі способи',value:''},{label:'Картка',value:'card'},{label:'Готівка',value:'cash'}]" aria-label="Спосіб оплати" @change="applyFilters"></custom-select></label><button class="button tonal" :disabled="loading">Застосувати</button><button class="icon-button" type="button" aria-label="Скинути фільтри" :disabled="loading" @click="resetFilters"><icon name="close"></icon></button></form><div v-if="view.name==='month'" class="month-transaction-list"><article v-for="row in state.transactions.items" :key="row.id" class="month-transaction"><span class="month-transaction-symbol"><icon :name="row.type==='card'?'wallet':'exchange'"></icon></span><div class="month-transaction-content"><button class="month-transaction-title" @click="openDialog('transaction',row)">{{row.title}}</button><div class="month-transaction-meta"><button type="button" class="month-category category-filter-link" :disabled="!row.category_id" @click="filterByCategory(row)">{{row.category||'Без категорії'}}</button><button type="button" class="month-payment category-filter-link" @click="filterByType(row)">{{row.type==='card'?'Картка':'Готівка'}}</button></div><div class="month-transaction-author"><button type="button" class="author-filter-link" :disabled="!row.user_id" @click="filterByUser(row)">{{row.author||'—'}}</button></div></div><div class="month-transaction-end"><div class="month-transaction-value"><time class="transaction-date-badge" :datetime="row.created_at"><icon name="calendar"></icon>{{dateLabel(row.created_at)}}</time><strong class="month-transaction-amount">−{{money(row.amount)}} <small>грн</small></strong></div><div class="row-actions"><button class="icon-button" :aria-label="'Редагувати: '+row.title" @click="openDialog('transaction',row)"><icon name="edit"></icon></button><button class="icon-button danger-text" :aria-label="'Видалити: '+row.title" @click="openDialog('deleteTransaction',row)"><icon name="trash"></icon></button></div></div></article></div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>Витрата</th><th>Категорія</th><th>Сума</th><th>Оплата</th><th>Автор / дата</th><th><span class="visually-hidden">Дії</span></th></tr></thead><tbody><tr v-for="row in state.transactions.items" :key="row.id"><td><button class="transaction-name" @click="openDialog('transaction',row)">{{row.title}}</button></td><td><button type="button" class="category-label category-filter-link" :disabled="!row.category_id" @click="filterByCategory(row)">{{row.category||'Без категорії'}}</button></td><td class="amount-cell">{{money(row.amount)}}<small>грн</small></td><td><button type="button" class="payment-label category-filter-link" @click="filterByType(row)">{{row.type==='card'?'Картка':'Готівка'}}</button></td><td class="author-cell"><button type="button" class="author-filter-link" :disabled="!row.user_id" @click="filterByUser(row)">{{row.author||'—'}}</button><time>{{dateLabel(row.created_at)}}</time></td><td><div class="row-actions"><button class="icon-button" :aria-label="'Редагувати: '+row.title" @click="openDialog('transaction',row)"><icon name="edit"></icon></button><button class="icon-button danger-text" :aria-label="'Видалити: '+row.title" @click="openDialog('deleteTransaction',row)"><icon name="trash"></icon></button></div></td></tr></tbody></table></div><div v-if="!state.transactions.items.length" class="empty-state"><span class="empty-icon"><icon name="wallet"></icon></span><h3>Транзакцій не знайдено</h3><p>Змініть фільтри або додайте витрату в бюджеті місяця.</p><button class="button text" @click="resetFilters">Скинути фільтри</button></div><div v-if="view.name!=='month'" class="pagination"><span>Сторінка {{state.transactions.page}} з {{state.transactions.last_page}}</span><div><button class="icon-button" aria-label="Попередня сторінка" :disabled="loading||state.transactions.page<=1" @click="page(-1)"><icon name="left"></icon></button><button class="icon-button" aria-label="Наступна сторінка" :disabled="loading||state.transactions.page>=state.transactions.last_page" @click="page(1)"><icon name="right"></icon></button></div></div></section><aside v-if="view.name==='month'" class="panel budgets-panel"><div class="section-heading"><div><h2>Бюджети категорій</h2><p>План і фактичні витрати</p></div><button class="icon-button tonal" aria-label="Додати бюджет категорії" @click="openDialog('budget')"><icon name="plus"></icon></button></div><button v-for="budget in state.budgets" :key="budget.id" :class="['budget-row',{'budget-overdrawn':budget.spent>budget.budget}]" @click="openDialog('budget',budget)"><div><strong>{{budget.name}}</strong><icon name="edit"></icon></div><p><span><span class="budget-spent-amount">{{money(budget.spent)}}</span> <small>витрачено</small></span><strong class="budget-planned-amount">{{money(budget.budget)}} грн</strong></p><div :class="['progress-track',{over:budget.spent>budget.budget}]"><span :style="{width:progress(budget)+'%'}"></span></div><span v-if="budget.spent>budget.budget" class="budget-warning">Перевищення {{money(budget.spent-budget.budget)}} грн</span></button><div v-if="!state.budgets.length" class="empty-state compact"><icon name="category"></icon><h3>Спочатку — бюджет</h3><p>Додайте категорію та її бюджет, щоб записувати витрати.</p><button class="button tonal" @click="openDialog('budget')">Додати бюджет</button></div></aside></div></template>
</template>
@endverbatim
